function readLocal(key){try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return []}}
function writeLocal(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}

function notify(message){const toast=$('#toast');toast.textContent=message;toast.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>toast.classList.remove('show'),2800)}
function setButtonBusy(button,busy,label){if(!button)return;button.disabled=busy;button.classList.toggle('busy',busy);if(label)button.querySelector('span:first-child')?button.querySelector('span:first-child').textContent=label:button.textContent=label}
function providerName(model){return (model.name || model.id).split(':')[0].replace('ByteDance','Bytedance')}
function cleanName(model){return (model.name || model.id).includes(':') ? (model.name || model.id).split(':').slice(1).join(':').trim() : (model.name || model.id)}
function providerKey(model){return providerName(model).toLowerCase().replace(/[^a-z]/g,'')}
function makeProviderMark(model){const wrap=document.createElement('span');wrap.className='provider-mark';const source=PROVIDER_LOGOS[providerKey(model)];if(source){const image=document.createElement('img');image.src=source;image.alt='';image.loading='lazy';wrap.append(image)}else{wrap.textContent=providerName(model).slice(0,1).toUpperCase()}return wrap}
function resetPageScroll(){const root=document.documentElement,previous=root.style.scrollBehavior;root.style.scrollBehavior='auto';window.scrollTo(0,0);root.style.scrollBehavior=previous}
function roundFive(value){return Math.max(5,Math.ceil(value/5)*5)}
function formatDong(value){return `₫${Math.round(value).toLocaleString('en-US')}`}
function safeArray(value,fallback){return Array.isArray(value)&&value.length?value:fallback}
function studioQualities(model){return DISPLAY_QUALITIES.filter(value=>safeArray(model.supported_resolutions,[]).includes(value))}


function updateQuote(){
  if(!state.selected)return;
  const seconds=Number($('#duration').value||8),quality=$('#quality').value||'720p',ratio=state.ratio;
  const mode=$('.composer-tab.active').textContent.includes('Image')?'image':'text';const rateInfo=selectRate(state.selected,quality,ratio,mode);
  if(!rateInfo.exact){state.currentQuote=null;clearTimeout(quoteTimer);quoteVersion++;$('#tokenCost').textContent='—';$('#cashCost').textContent='This model needs a provider-specific quote.';$('#supplierLabel').textContent='Provider price';$('#supplierCost').textContent='See model details';$('#durationCost').textContent=seconds+' seconds';$('#qualityCost').textContent=quality;$('#aspectCost').textContent=ratio;$('#outputCost').textContent=state.outputs+' variations';$('#generateCost').textContent='Quote required';return}
  const aspectFactor=1;
  const supplierUSD=supplierCost(rateInfo,seconds,state.outputs);
  const protectedCostVND=supplierUSD*FX_VND_PER_USD*OPERATING_BUFFER;
  const retailVND=protectedCostVND/(1-TARGET_MARGIN);
  const tokens=roundFive(retailVND/TOKEN_FLOOR_VND);
  $('#tokenCost').textContent=tokens.toLocaleString('en-US');
  $('#cashCost').textContent=rateInfo.exact?`about ${formatDong(tokens*TOKEN_FLOOR_VND)} at the ₫500/token reference rate`:`reserve up to ${formatDong(tokens*TOKEN_FLOOR_VND)} · final cost settles after render`;
  $('#supplierLabel').textContent=rateInfo.exact?'Model price':'Price estimate';
  $('#supplierCost').textContent=`$${supplierUSD.toFixed(2)}${rateInfo.exact?'':' est.'}`;
  $('#durationCost').textContent=`${seconds} seconds`;
  $('#qualityCost').textContent=quality;
  $('#aspectCost').textContent=ratio;
  $('#outputCost').textContent=`${state.outputs} ${state.outputs===1?'variation':'variations'}`;
  $('#generateCost').textContent=`${tokens} TOKENS`;
  state.currentQuote={tokens,supplierUSD,seconds,quality,ratio,outputs:state.outputs,exact:rateInfo.exact,mode,priceBasis:rateInfo.basis,modelId:state.selected.id,modelName:cleanName(state.selected)};
  updateForecast();
  clearTimeout(quoteTimer);quoteTimer=setTimeout(requestServerQuote,120);
}

async function requestServerQuote(){
  if(!state.currentQuote)return;const version=++quoteVersion,quote=state.currentQuote;
  const params=new URLSearchParams({model:quote.modelId,resolution:quote.quality,aspect:quote.ratio,duration:String(quote.seconds),outputs:String(quote.outputs),mode:quote.mode});
  try{const response=await fetch(`/api/quote?${params}`);if(!response.ok)return;const authoritative=await response.json();if(version!==quoteVersion||!state.currentQuote||state.currentQuote.modelId!==authoritative.model)return;
    $('#tokenCost').textContent=authoritative.tokens.toLocaleString('en-US');$('#cashCost').textContent=authoritative.exact?`about ${formatDong(authoritative.retailVnd)} at the ₫500/token reference rate`:`reserve up to ${formatDong(authoritative.retailVnd)} · final cost settles after render`;$('#supplierLabel').textContent=authoritative.exact?'Model price':'Price estimate';$('#supplierCost').textContent=`$${authoritative.supplierUsd.toFixed(2)}${authoritative.exact?'':' est.'}`;$('#generateCost').textContent=`${authoritative.tokens} TOKENS`;state.currentQuote={...quote,tokens:authoritative.tokens,supplierUSD:authoritative.supplierUsd,exact:authoritative.exact};updateForecast();
  }catch{}
}

function populateControls(){
  const model=state.selected;if(!model)return;
  $('#selectedModelName').textContent=cleanName(model);
  const reportedQualities=safeArray(model.supported_resolutions,[]);
  const qualities=DISPLAY_QUALITIES.filter(value=>reportedQualities.includes(value));
  const durations=safeArray(model.supported_durations,[5,8,10]);
  const aspects=safeArray(model.supported_aspect_ratios,['16:9']);
  const quality=$('#quality');const previousQuality=quality.value;quality.replaceChildren();
  qualities.forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=value;quality.append(option)});
  if(!qualities.length){const option=document.createElement('option');option.value='';option.textContent='Unavailable';quality.append(option)}
  quality.value=qualities.includes(previousQuality)?previousQuality:(qualities.includes('720p')?'720p':qualities[0]);
  const qualityOptions=$('#qualityOptions');qualityOptions.replaceChildren();
  qualities.forEach(value=>{const supported=true,button=document.createElement('button');button.type='button';button.textContent=value;button.dataset.quality=value;button.disabled=!supported;button.title=supported?`${value} is reported by ${providerName(model)}`:`${providerName(model)} does not report ${value} for this model`;button.classList.toggle('active',value===quality.value);qualityOptions.append(button)});
  const duration=$('#duration');const previousDuration=Number(duration.value);duration.replaceChildren();
  durations.forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=`${value} seconds`;duration.append(option)});
  duration.value=durations.includes(previousDuration)?String(previousDuration):String(durations.includes(8)?8:durations[Math.min(2,durations.length-1)]);
  $('#durationValue').textContent=`${duration.value}s`;
  const presets=$('#durationPresets');presets.replaceChildren();durations.length<=8&&durations.forEach(value=>{const button=document.createElement('button');button.type='button';button.textContent=`${value}s`;button.dataset.duration=value;button.classList.toggle('active',String(value)===duration.value);presets.append(button)});updateDurationButtons();
  if(!aspects.includes(state.ratio))state.ratio=aspects.includes('16:9')?'16:9':aspects[0];
  const ratios=$('#ratios');ratios.replaceChildren();
  DISPLAY_ASPECTS.forEach(value=>{const supported=aspects.includes(value),button=document.createElement('button');button.type='button';button.textContent=value;button.dataset.ratio=value;button.disabled=!supported;button.title=supported?`${value} is reported by ${providerName(model)}`:`${providerName(model)} does not report ${value}`;button.classList.toggle('active',value===state.ratio);ratios.append(button)});
  updateQuote();
}

function makeTags(model){
  const tags=document.createElement('div');tags.className='model-tags';
  const resolutions=studioQualities(model).slice(0,2);
  const durations=safeArray(model.supported_durations,[]),rate=isDirectlyConfigurable(model)?selectRate(model,resolutions[0]||'720p'):null;
  const values=[...resolutions,durations.length?`up to ${Math.max(...durations)}s`:null,rate&&rate.exact?`${Number(rate.rate.toFixed(5))}/s · ${resolutions[0]} · 16:9`:null,model.generate_audio?'Audio':null,safeArray(model.supported_frame_images,[]).length?'Image input':null,!isDirectlyConfigurable(model)?'Edit / utility':null].filter(Boolean);
  values.forEach(value=>{const span=document.createElement('span');span.textContent=value;tags.append(span)});return tags;
}

