function renderNotifications(){const notifications=getNotifications(),root=$('#notificationList');root.replaceChildren();notifications.forEach(item=>{const article=document.createElement('article');article.dataset.id=item.id;article.classList.toggle('unread',!item.read);const orb=document.createElement('i');orb.classList.toggle('new',!item.read);const body=document.createElement('div'),title=document.createElement('strong'),copy=document.createElement('p'),time=document.createElement('small'),actions=document.createElement('div');title.textContent=item.title;copy.textContent=item.message;time.textContent=item.time;actions.className='notification-item-actions';const read=document.createElement('button');read.type='button';read.dataset.notificationRead=item.id;read.textContent=item.read?'Read':'Mark read';read.disabled=item.read;const remove=document.createElement('button');remove.type='button';remove.dataset.notificationDelete=item.id;remove.textContent='Delete';actions.append(read,remove);body.append(title,copy,time,actions);article.append(orb,body);root.append(article)});if(!notifications.length){const empty=document.createElement('div');empty.className='notification-empty';empty.innerHTML='<span>✓</span><strong>All clear</strong><small>No notifications on this device.</small>';root.append(empty)}const unread=notifications.filter(item=>!item.read).length,badge=$('#notificationCount');badge.textContent=unread;badge.hidden=!unread;$('#notificationButton').setAttribute('aria-label',unread?`Open notifications, ${unread} unread`:'Open notifications')}
