function loadBrand(){const saved=readLocal('hcmc-brand');const brand=Array.isArray(saved)?saved[0]:null;if(!brand)return updateBrandPreview();$('#brandName').value=brand.name||'';$('#brandDirection').value=brand.direction||'';for(const [id,key] of [['brandTagline','tagline'],['brandVoice','voice'],['brandCta','cta'],['brandAvoid','avoid']])$('#'+id).value=brand[key]||'';state.brandColor=brand.color||'#dfff5b';document.querySelectorAll('[data-swatch]').forEach(button=>button.classList.toggle('active',button.dataset.swatch===state.brandColor));updateBrandPreview()}
function updateBrandPreview(){const name=$('#brandName').value.trim()||'Your studio',direction=$('#brandDirection').value.trim()||'A consistent visual world for every frame you make.',classes={'#dfff5b':'accent-lime','#ff6542':'accent-orange','#6f8cff':'accent-blue','#ef79d2':'accent-pink','#f2eee4':'accent-white'};$('#brandPreviewName').textContent=name;$('#brandMonogram').textContent=name.slice(0,1).toUpperCase();$('#brandPreviewDirection').textContent=direction;$('#brandColorCode').textContent=state.brandColor.toUpperCase();$('#brandPreview').className=`brand-preview ${classes[state.brandColor]||'accent-lime'}`;$('#brandBriefText').textContent=brandBrief()||'Add your creative direction to build a brief.'}
