renderProjects();renderTemplates();renderDirectorBoard();renderStoryboard();renderHistory();renderGenerationQueue();renderNotifications();loadBrand();loadAssets();renderCommands();applyTheme(currentPreferences().theme||'dark');showAuthStatus();loadSession();loadModels();const savedPrompt=localStorage.getItem('hcmc-active-prompt');if(savedPrompt){$('#prompt').value=savedPrompt;$('#charCount').textContent=savedPrompt.length}const savedConcept=localStorage.getItem('hcmc-concept-frame');if(savedConcept){$('#previewCard>img').src=savedConcept;$('#previewDialog img').src=savedConcept}window.addEventListener('online',updateOnlineState);window.addEventListener('offline',updateOnlineState);const intro=$('#introSequence');intro.addEventListener('animationend',event=>{if(event.target===intro&&event.animationName==='introExit')finishIntro()});function finishIntro(){intro?.remove();document.body.classList.remove('intro-running')}setTimeout(finishIntro,2550);
const studioViews=['create','explore','projects','templates','assets','storyboard','brand','history','usage','plans','connections','docs','settings','account','policies','billing'];function applyRoute(){const anchor=location.hash.slice(1);if(['privacy-policy','payment-policy','use-policy','account-policy'].includes(anchor)){switchView('policies',false);requestAnimationFrame(()=>document.getElementById(anchor)?.scrollIntoView({block:'start'}));return}const route=location.hash.slice(1)==='pricing'?'plans':location.hash.slice(1);if(studioViews.includes(route))switchView(route,false);else showLanding(false)}applyRoute();window.addEventListener('popstate',applyRoute);window.addEventListener('hashchange',()=>{if(['privacy-policy','payment-policy','use-policy','account-policy'].includes(location.hash.slice(1)))return;applyRoute()});

// Focused local UX improvements. No provider requests are made by these controls.
$('#renameProjectForm').addEventListener('submit',event=>{event.preventDefault();const input=$('#renameProjectName'),name=input.value.trim();if(!name){input.setCustomValidity('Enter a project name.');input.reportValidity();return}if(updateProject(editingProjectId,{name})){$('#renameProjectDialog').close();notify('Project renamed')}});
$('#renameProjectName').addEventListener('input',event=>event.target.setCustomValidity(''));
$('#undoProjectDelete').addEventListener('click',()=>{const trash=readLocal('hcmc-project-trash'),project=trash[0];if(!project){$('#projectUndo').hidden=true;return}const projects=readLocal('hcmc-projects');if(!projects.some(item=>item.id===project.id))projects.unshift(project);if(!writeLocal('hcmc-projects',projects))return notify('Storage is full. Could not restore project.');writeLocal('hcmc-project-trash',trash.slice(1));$('#projectUndo').hidden=trash.length<=1;renderProjects();notify('Project restored')});
$('#dismissProjectUndo').addEventListener('click',()=>$('#projectUndo').hidden=true);
if(readLocal('hcmc-project-trash').length)$('#projectUndo').hidden=false;
let assetPreviewUrl='';
function previewAsset(asset){const dialog=$('#assetPreviewDialog'),content=$('#assetPreviewContent');content.replaceChildren();if(assetPreviewUrl)URL.revokeObjectURL(assetPreviewUrl);assetPreviewUrl=URL.createObjectURL(asset.blob);const media=document.createElement(asset.category==='image'?'img':asset.category==='video'?'video':'audio');media.src=assetPreviewUrl;if(asset.category==='image')media.alt=asset.name;else{media.controls=true;media.preload='metadata'}content.append(media);$('#assetPreviewTitle').textContent=asset.name;$('#assetPreviewMeta').textContent=asset.category.toUpperCase()+' · '+(asset.size/1024/1024).toFixed(1)+' MB · stored on this device';dialog.showModal()}
$('#assetPreviewDialog').addEventListener('close',()=>{$('#assetPreviewContent').replaceChildren();if(assetPreviewUrl)URL.revokeObjectURL(assetPreviewUrl);assetPreviewUrl=''});
// Standard keyboard navigation for the existing generation-mode tabs.
const modeTabs=[...document.querySelectorAll('.composer-tab')];
function syncModeTabFocus(){modeTabs.forEach(tab=>tab.tabIndex=tab.getAttribute('aria-selected')==='true'?0:-1)}
syncModeTabFocus();modeTabs.forEach((tab,index)=>{tab.addEventListener('click',syncModeTabFocus);tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%modeTabs.length;else if(event.key==='ArrowLeft')next=(index+modeTabs.length-1)%modeTabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=modeTabs.length-1;else return;event.preventDefault();modeTabs[next].click();modeTabs[next].focus()})});

$('#retryCatalog').addEventListener('click',loadModels);

function brandBrief(){return [['Brand',$('#brandName').value],['Visual direction',$('#brandDirection').value],['Tagline',$('#brandTagline').value],['Voice',$('#brandVoice').value],['Call to action',$('#brandCta').value],['Avoid',$('#brandAvoid').value]].filter(([,value])=>value.trim()).map(([label,value])=>label+': '+value.trim()).join('\n')+($('#brandDirection').value.trim()?'\nAccent color: '+state.brandColor:'')}
for(const id of ['brandTagline','brandVoice','brandCta','brandAvoid'])$('#'+id).addEventListener('input',updateBrandPreview);
$('#copyBrandBrief').addEventListener('click',async()=>{const brief=brandBrief();if(!brief)return notify('Add brand details first');try{await navigator.clipboard.writeText(brief);notify('Brand brief copied')}catch{notify('Clipboard unavailable. Select and copy the brief text.')}});
async function startGoogleSignIn(){const error=$('#authError'),button=$('#googleSignIn');button.disabled=true;error.classList.remove('success');error.textContent='Checking Google sign-in…';try{const response=await fetch('/api/runtime');if(!response.ok)throw Error();const runtime=await response.json();if(!runtime.oauthConfigured){error.textContent='Google sign-in is not connected yet. You can use email to create a local account below.';$('#authEmail').focus();return}location.assign('/auth/google')}catch{error.textContent='Could not reach the account server. Please retry.'}finally{button.disabled=false}}
$('#togglePassword').addEventListener('click',()=>{const input=$('#authPassword'),show=input.type==='password';input.type=show?'text':'password';$('#togglePassword').textContent=show?'Hide password':'Show password';$('#togglePassword').setAttribute('aria-pressed',String(show))});
$('#previewPaymentFlow').addEventListener('click',()=>{$('#paymentPreviewState').hidden=false;$('#paymentPreviewState').scrollIntoView({block:'nearest',behavior:'smooth'})});
function renderProviderPrices(){
  const quality=$('#priceResolution').value,aspect=$('#priceAspect').value,mode=$('#priceMode').value,body=$('#providerPriceRows');body.replaceChildren();
  const rows=state.models.filter(model=>isDirectlyConfigurable(model)&&model.supported_resolutions?.includes(quality)&&model.supported_aspect_ratios?.includes(aspect)&&(mode!=='image'||model.supported_frame_images?.length)).map(model=>({model,price:selectRate(model,quality,aspect,mode)})).sort((a,b)=>(a.price.exact?a.price.rate:Infinity)-(b.price.exact?b.price.rate:Infinity));
  for(const {model,price} of rows){
    const row=document.createElement('tr');
    const output=price.exact?'$'+Number(price.rate.toFixed(5)):model.pricing_skus?.video_tokens?'$'+Number((Number(model.pricing_skus.video_tokens)*1000000).toFixed(3))+' / M video tokens':'Provider quote required';
    for(const value of [cleanName(model),output,price.exact?'$'+Number(price.inputCost.toFixed(4)):'—']){const cell=document.createElement('td');cell.textContent=value;row.append(cell)}
    const cell=document.createElement('td'),link=document.createElement('a');link.href='https://openrouter.ai/'+model.id;link.target='_blank';link.rel='noopener noreferrer';link.textContent='OpenRouter ↗';cell.append(link);row.append(cell);body.append(row);
  }
  $('#priceSourceNote').textContent=(state.live?'Live catalog':'Verified snapshot')+' · '+(state.catalogDate?new Date(state.catalogDate).toLocaleDateString():'date unavailable')+' · '+rows.length+' compatible models. Sorted by quoted output cost; token-billed entries without a verified conversion are listed separately.';
}
for(const id of ['priceResolution','priceAspect','priceMode'])$('#'+id).addEventListener('change',renderProviderPrices);
function storySnapshot(){return {shots:structuredClone(readLocal('hcmc-storyboard')),edges:structuredClone(storyboardEdges())}}
function restoreStory(snapshot){writeLocal('hcmc-storyboard',Array.isArray(snapshot)?snapshot:snapshot.shots);if(!Array.isArray(snapshot))writeLocal('hcmc-story-edges',snapshot.edges);state.storyConnectFrom=null;renderStoryboard()}
function wouldCycle(edges,from,to){const queue=[to],seen=new Set();while(queue.length){const id=queue.pop();if(id===from)return true;if(seen.has(id))continue;seen.add(id);edges.filter(edge=>edge.from===id).forEach(edge=>queue.push(edge.to))}return false}
$('#simplifyStory').addEventListener('click',()=>{const before=storyboardEdges(),clean=[];for(const edge of before){if(clean.some(item=>item.from===edge.from||item.to===edge.to)||wouldCycle(clean,edge.from,edge.to))continue;clean.push(edge)}if(clean.length===before.length)return notify('Connections already form simple sequences.');state.storyUndo.push(storySnapshot());state.storyRedo=[];writeLocal('hcmc-story-edges',clean);renderStoryboard();notify('Branch connections simplified · Undo is available')});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.storyConnectFrom){state.storyConnectFrom=null;renderStoryboard()}});

let promotionTimer;
async function loadPromotion(){try{const response=await fetch('/api/promotion');if(!response.ok)return;const offer=await response.json();if(!offer.configured){startOfferPreview();return}clearInterval(promotionTimer);const tick=()=>{const remaining=Date.parse(offer.endsAt)-Date.now();$('#publicOfferTitle').textContent='30% off '+offer.plan+' · first month';$('#publicOfferState').textContent=remaining>0?'Offer preview · ends in':'Offer ended';$('#publicOfferClock').textContent=clockLabel(Math.max(0,remaining));$('#launchOfferTitle').textContent='30% off '+offer.plan+' · first month';$('#launchOfferCopy').textContent='Preview offer only. Checkout is not connected. After the first month, the standard monthly price applies.';$('#launchOfferPrice').textContent=formatDong(offer.promotionalPrice)+' first month · then '+formatDong(offer.standardPrice)+'/month';if(remaining<=0){$('#launchOfferState').textContent='Offer ended';$('#launchOfferCountdown').textContent='Promotion expired';clearInterval(promotionTimer);return}const seconds=Math.floor(remaining/1000),days=Math.floor(seconds/86400),hours=Math.floor(seconds%86400/3600),minutes=Math.floor(seconds%3600/60);$('#launchOfferState').textContent='Ends '+new Date(offer.endsAt).toLocaleString();$('#launchOfferCountdown').textContent=days+'d '+hours+'h '+minutes+'m '+(seconds%60)+'s'};tick();promotionTimer=setInterval(tick,1000)}catch{}}
loadPromotion();

function clockLabel(ms){const s=Math.max(0,Math.ceil(ms/1000));return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(v=>String(v).padStart(2,'0')).join(':')}
function startOfferPreview(){const key='hcmc-offer-preview-end';let end=Number(sessionStorage.getItem(key));if(!end){end=Date.now()+86400000;sessionStorage.setItem(key,String(end))}const tick=()=>{const left=end-Date.now();$('#publicOfferClock').textContent=clockLabel(left);if(left<=0){$('#publicOfferState').textContent='Offer preview ended';clearInterval(promotionTimer)}};tick();promotionTimer=setInterval(tick,1000)}

// Suspend decorative motion when it cannot be seen; preserve its original visual design.
const ambientObserver=new IntersectionObserver(entries=>{for(const entry of entries)entry.target.classList.toggle('motion-offscreen',!entry.isIntersecting)},{rootMargin:'100px'});document.querySelectorAll('.hero-section,.workflow-visual').forEach(el=>ambientObserver.observe(el));document.addEventListener('visibilitychange',()=>document.body.classList.toggle('motion-suspended',document.hidden));
